+  chronological order (oldest first).
+
+Errors:
+  - Missing or non-string order_id.
+  - Extra/unknown argument fields.
+  - include_history that is not a boolean.
+  - Unknown order_id (order not found).
+  - Unknown tool name.`,
+  inputSchema: {
+    type: 'object',
+    properties: {
+      order_id: {
+        type: 'string',
+        description: 'The unique identifier of the order.'
+      },
+      include_history: {
+        type: 'boolean',
+        default: false,
+        description: 'Whether to include the chronological status history. Defaults to false.'
+      }
+    },
+    required: ['order_id'],
+    additionalProperties: false
+  },
+  annotations: {
+    readOnlyHint: true,
+    destructiveHint: false,
+    idempotentHint: true,
+    openWorldHint: false
+  }
+};
+
+const TOOLS = [ORDER_STATUS_TOOL];
+
+const ALLOWED_FIELDS = new Set(['order_id', 'include_history']);
+
+function parseArgs(args) {
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object.');
+  }
+
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_FIELDS.has(key)) {
+      throw new Error(
+        `Invalid argument: unexpected field '${key}'. Allowed fields are: order_id, include_history.`
+      );
+    }
+  }
+
+  if (!('order_id' in args)) {
+    throw new Error('Missing required argument: order_id.');
+  }
+  if (typeof args.order_id !== 'string') {
+    throw new Error('Invalid argument: order_id must be a string.');
+  }
+  if (args.order_id.length === 0) {
+    throw new Error('Invalid argument: order_id must not be empty.');
+  }
+
+  let includeHistory = false;
+  if ('include_history' in args) {
+    if (typeof args.include_history !== 'boolean') {
+      throw new Error('Invalid argument: include_history must be a boolean.');
+    }
+    includeHistory = args.include_history;
+  }
+
+  return { order_id: args.order_id, include_history: includeHistory };
+}
+
+export async function listTools() {
+  return TOOLS;
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'order_status') {
+    throw new Error(
+      `Unknown tool: '${name}'. Available tools: ${TOOLS.map((t) => t.name).join(', ')}.`
+    );
+  }
+
+  const { order_id, include_history } = parseArgs(args);
+
+  const order = orders[order_id];
+  if (!order) {
+    throw new Error(`Order not found: '${order_id}'.`);
